<script setup lang="ts">
import { nextTick, onMounted, ref } from 'vue'
import { api, action } from '../api'
import Pagination from './Pagination.vue'
import { usePagination } from '../pagination'
import MarkdownView from './MarkdownView.vue'
const sources=ref<any[]>([]),suggested=ref<string[]>([]),items=ref<any[]>([]),page=ref(1),pageSize=ref(10),pages=ref(1),total=ref(0),filter=ref(''),applied=ref(''),status=ref(''),sourceId=ref(''),busy=ref(false),scanResult=ref<any>(null),viewed=ref<any>(null)
const sourcePager=usePagination(()=>sources.value)
const form=ref(false),dialog=ref<HTMLDialogElement|null>(null),editing=ref<any>(null),name=ref(''),root=ref(''),enabled=ref(false),depth=ref(4)
async function loadSources(){const value=await api('/governance/skill-sources');sources.value=value.items;suggested.value=value.suggested_roots}
async function load(target=page.value){const data=await api('/governance/discovered-skills?'+new URLSearchParams({page:String(target),page_size:String(pageSize.value),q:applied.value,status:status.value,source_id:sourceId.value}));items.value=data.items;page.value=data.page;pages.value=data.pages;total.value=data.total}
async function run(task:()=>Promise<void>,message=''){busy.value=true;await action(task,message);busy.value=false}
async function edit(item?:any){editing.value=item||null;name.value=item?.name||'';root.value=item?.root||suggested.value[0]||'';enabled.value=item?.enabled||false;depth.value=item?.max_depth??4;form.value=true;await nextTick();dialog.value?.showModal()}
async function save(){await run(async()=>{await api('/governance/skill-sources'+(editing.value?'/'+editing.value.id:''),editing.value?'PATCH':'POST',{name:name.value,root:root.value,enabled:enabled.value,max_depth:depth.value,...(editing.value?{revision:editing.value.revision}:{})});form.value=false;await loadSources();await load()},'扫描目录已保存')}
async function scan(item:any){await run(async()=>{const result=await api('/governance/skill-sources/'+item.id+'/scan','POST');await loadSources();await load(1);scanResult.value=result},'扫描完成；新发现内容默认停用，请审阅后启用')}
async function toggleSource(item:any){await run(async()=>{await api('/governance/skill-sources/'+item.id,'PATCH',{name:item.name,root:item.root,enabled:!item.enabled,max_depth:item.max_depth,revision:item.revision});await loadSources();await load();viewed.value=null},item.enabled?'已暂停目录；其中 Skill 不再通过 MCP 提供':'已启用扫描目录')}
async function remove(item:any){if(!window.confirm(`移除“${item.name}”扫描目录及发现记录？原文件保留。`))return;await run(async()=>{await api('/governance/skill-sources/'+item.id+'?revision='+item.revision,'DELETE');if(sourceId.value===item.id)sourceId.value='';await loadSources();await load();viewed.value=null},'目录与发现记录已移除，原文件保留')}
async function toggle(item:any){await run(async()=>{await api('/governance/discovered-skills/'+item.id,'PATCH',{enabled:item.status!=='enabled',revision:item.revision});await load()},item.status==='enabled'?'Skill 已在本服务停用':'Skill 已在本服务启用')}
async function read(item:any){await run(async()=>{viewed.value=await api('/governance/discovered-skills/'+item.id)},'')}
async function apply(){applied.value=filter.value;await run(()=>load(1))}
onMounted(()=>run(async()=>{await loadSources();await load()}))
</script>
<template>
 <section class="discovery-panel">
  <div class="panel-heading"><div><h2>全局 Skill 发现</h2><p class="muted">显式登记目录，按需扫描；启停只作用于 Memory Center，原文件与宿主配置保持不变。</p></div><button @click="edit()" :disabled="busy">＋ 添加扫描目录</button></div>
  <div class="discovery-body">
   <details class="discovery-sources" open><summary>扫描目录 · {{sources.length}}</summary><p v-if="!sources.length" class="muted">还没有扫描目录。添加一个服务端可访问的全局 Skill 目录开始发现。</p><div v-for="item in sourcePager.rows.value" :key="item.id" class="source-row"><div><h3>{{item.name}} <span class="badge">{{item.enabled?'扫描已启用':'扫描已暂停'}}</span></h3><p class="path">{{item.root}}</p><p class="muted">{{item.scan_count}} 个 Skill · 深度 {{item.max_depth}} · {{item.last_scan?new Date(item.last_scan).toLocaleString():'尚未扫描'}}</p></div><div class="actions"><button @click="scan(item)" :disabled="busy||!item.enabled">立即扫描</button><button @click="toggleSource(item)" :disabled="busy">{{item.enabled?'暂停扫描':'启用扫描'}}</button><button @click="edit(item)" :disabled="busy">配置</button><button class="danger" @click="remove(item)" :disabled="busy">移除目录</button></div></div><Pagination v-if="sources.length" :page="sourcePager.page.value" :page-size="sourcePager.pageSize.value" :total="sourcePager.total.value" :pages="sourcePager.pages.value" label="扫描目录" :busy="busy" @change="sourcePager.page.value=$event" @size="sourcePager.pageSize.value=$event;sourcePager.reset()"/></details>
   <p v-if="scanResult" class="muted">最近扫描发现 {{scanResult.found}} 个 Skill；跳过 {{scanResult.skipped_symlinks}} 个符号链接。</p><form class="toolbar" @submit.prevent="apply"><input v-model="filter" placeholder="搜索 Skill 名称、描述或路径" aria-label="筛选发现 Skill"><select v-model="sourceId" aria-label="Skill 来源目录" @change="apply"><option value="">全部目录</option><option v-for="s in sources" :key="s.id" :value="s.id">{{s.name}}</option></select><select v-model="status" aria-label="发现 Skill 状态" @change="apply"><option value="">全部状态</option><option value="enabled">已选择启用</option><option value="disabled">已停用</option><option value="missing">源文件缺失</option></select><button :disabled="busy">筛选</button></form>
   <div class="table-wrap"><table><thead><tr><th>Skill</th><th>来源</th><th>本服务状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><h3>{{item.name}}</h3><p class="muted skill-description">{{item.description}}</p></td><td><span>{{item.source_name}}</span><p class="mono">{{item.relative_path}}</p></td><td><span class="badge">{{!item.source_enabled?'目录已暂停':item.status==='enabled'?'已启用':item.status==='missing'?'源文件缺失':'已停用'}}</span></td><td class="actions"><button @click="read(item)" :disabled="busy||!item.source_enabled||item.status==='missing'">查看</button><button @click="toggle(item)" :disabled="busy||(!item.source_enabled&&item.status!=='enabled')||item.status==='missing'">{{item.status==='enabled'?'停用':'启用'}}</button></td></tr></tbody></table><p v-if="!items.length" class="empty">{{total?'请调整筛选条件':'暂无发现结果。启用一个扫描目录，然后点击“立即扫描”。'}}</p></div>
   <Pagination :page="page" :page-size="pageSize" :total="total" :pages="pages" label="发现 Skill" :busy="busy" @change="run(()=>load($event))" @size="pageSize=$event;run(()=>load(1))"/>
   <div v-if="viewed" class="discovered-reader"><div class="panel-heading"><div><h2>{{viewed.name}}</h2><p class="muted">{{viewed.source_name}} · {{viewed.relative_path}}</p></div><button @click="viewed=null">关闭</button></div><MarkdownView :content="viewed.body"/></div>
  </div>
 </section>
 <dialog v-if="form" ref="dialog" @cancel.prevent="form=false"><form @submit.prevent="save"><h2>{{editing?'配置扫描目录':'添加扫描目录'}}</h2><label>目录名称<input v-model="name" required maxlength="120" placeholder="例如：共享 Skill"></label><label>目录绝对路径<input v-model="root" required :readonly="!!editing" placeholder="/skills/shared"></label><p class="muted">容器运行时填写挂载后的路径；支持按设定深度查找 SKILL.md，不跟随符号链接。{{suggested.length?'可用发布目录：'+suggested.join('、'):''}}</p><label>扫描深度<input type="number" v-model.number="depth" min="0" max="8" required></label><label class="check"><input type="checkbox" v-model="enabled">启用此目录的手动扫描与 Skill 提供</label><p class="muted">新发现内容默认停用；内容变化后重新扫描会停用该 Skill，需要重新审阅启用。</p><div class="dialog-actions"><button type="button" @click="form=false">取消</button><button class="primary" :disabled="busy">保存扫描目录</button></div></form></dialog>
</template>
